package harmonised.pmmo.events.impl;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import harmonised.pmmo.api.APIUtils;
import harmonised.pmmo.api.enums.EventType;
import harmonised.pmmo.api.enums.ReqType;
import harmonised.pmmo.config.Config;
import harmonised.pmmo.core.Core;
import harmonised.pmmo.features.party.PartyUtils;
import harmonised.pmmo.features.veinmining.VeinMiningLogic;
import harmonised.pmmo.storage.ChunkDataHandler;
import harmonised.pmmo.storage.ChunkDataProvider;
import harmonised.pmmo.storage.IChunkData;
import harmonised.pmmo.util.Messenger;
import harmonised.pmmo.util.Reference;
import harmonised.pmmo.util.RegistryUtil;
import harmonised.pmmo.util.TagUtils;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.CropBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.LevelChunk;
import net.minecraftforge.event.level.BlockEvent.BreakEvent;

public class BreakHandler {

	@SuppressWarnings("resource")
	public static void handle(BreakEvent event) {
		Core core = Core.get(event.getPlayer().level());
		boolean serverSide = !event.getPlayer().level().isClientSide;
		if (!core.isActionPermitted(ReqType.BREAK, event.getPos(), event.getPlayer())) {
			event.setCanceled(true);
			Messenger.sendDenialMsg(ReqType.BREAK, event.getPlayer(), event.getState().getBlock().getName());
			return;
		}
		CompoundTag eventHookOutput = new CompoundTag();
		if (serverSide){
			eventHookOutput = core.getEventTriggerRegistry().executeEventListeners(EventType.BLOCK_BREAK, event, new CompoundTag());
			if (eventHookOutput.getBoolean(APIUtils.IS_CANCELLED)) {
				event.setCanceled(true);
				return;
			}
		}
		//Process perks on both sides. note that only server-side perks will affect xp outputs.
		CompoundTag perkOutput = TagUtils.mergeTags(eventHookOutput, core.getPerkRegistry().executePerk(EventType.BLOCK_BREAK, event.getPlayer(), eventHookOutput));
		if (serverSide) {
			Map<String, Long> xpAward = calculateXpAward(core, event, perkOutput);
			List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange((ServerPlayer) event.getPlayer());
			core.awardXP(partyMembersInRange, xpAward);
			//update ChunkData to remove the block from the placed map
			//if a cascading breaking crop block, add the breaker value.
			LevelChunk chunk = (LevelChunk) event.getLevel().getChunk(event.getPos());
			chunk.getCapability(ChunkDataProvider.CHUNK_CAP).ifPresent(cap -> {
				cap.delPos(event.getPos());
				if (event.getLevel().getBlockState(event.getPos()).is(Reference.CASCADING_BREAKABLES))
					cap.setBreaker(event.getPos(), event.getPlayer().getUUID());
			});;
			chunk.setUnsaved(true);
		}
		//==============Process Vein Miner Logic==================
		if (core.getMarkedPos(event.getPlayer().getUUID()).equals(event.getPos())) {
			BlockState block = event.getLevel().getBlockState(event.getPos());
			Item tool = event.getPlayer().getMainHandItem().getItem();
			if (!Config.VEIN_BLACKLIST.get().contains(RegistryUtil.getId(tool).toString())) {
				VeinMiningLogic.applyVein((ServerPlayer) event.getPlayer(), event.getPos());
			}
		}
	}

	private static Map<String, Long> calculateXpAward(Core core, BreakEvent event, CompoundTag dataIn) {
		Map<String, Long> outMap = core.getExperienceAwards(EventType.BLOCK_BREAK, event.getPos(), (Level)event.getLevel(), event.getPlayer(), dataIn); 
		LevelChunk chunk = (LevelChunk) event.getLevel().getChunk(event.getPos());
		IChunkData cap = chunk.getCapability(ChunkDataProvider.CHUNK_CAP).orElseGet(ChunkDataHandler::new);
		if (cap.playerMatchesPos(event.getPlayer(), event.getPos())) {
			//Do not apply self-place penalty to crops
			BlockState cropState = event.getLevel().getBlockState(event.getPos()); 
			if (cropState.getBlock() instanceof CropBlock && ((CropBlock)cropState.getBlock()).isMaxAge(cropState))
				return outMap;
			double xpModifier = Config.REUSE_PENALTY.get();
			if (xpModifier == 0) return new HashMap<>();
			Map<String, Long> modifiedOutMap = new HashMap<>();
			outMap.forEach((k, v) -> modifiedOutMap.put(k, (long)((double)v * xpModifier)));
			return modifiedOutMap;
		}
		return outMap;
	}
}

package harmonised.pmmo.events.impl;

import java.util.List;
import java.util.Map;
import java.util.UUID;

import harmonised.pmmo.api.enums.EventType;
import harmonised.pmmo.core.Core;
import harmonised.pmmo.features.party.PartyUtils;
import harmonised.pmmo.storage.ChunkDataHandler;
import harmonised.pmmo.storage.ChunkDataProvider;
import harmonised.pmmo.util.Reference;
import harmonised.pmmo.util.TagUtils;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraftforge.event.level.BlockEvent.CropGrowEvent;

public class CropGrowHandler {

	public static void handle(CropGrowEvent.Post event) {
		Level level = (Level) event.getLevel();
		if (!level.isClientSide) {
			Core core = Core.get(level);

			//if this block grew to exist because of a cascading block, return the block which spawned it
			BlockPos sourcePos = getParentPos(level, event.getState(), event.getPos());
			//get the owner of the source block to know who to give the grow XP to.
			ChunkDataHandler cap = (ChunkDataHandler) level.getChunkAt(sourcePos).getCapability(ChunkDataProvider.CHUNK_CAP).orElseGet(ChunkDataHandler::new);
			UUID placerID = cap.checkPos(sourcePos);
			ServerPlayer player = event.getLevel().getServer().getPlayerList().getPlayer(placerID);

			//if there is no owning player, return as there is no XP to give
			if (player == null) return;

			//this is a redundant call to make sure cascading blocks have their owner set.  for non-cascading it just reassigns the same value
			cap.addPos(event.getPos(), placerID);

			//Execute event triggers from addons
			CompoundTag hookOutput = core.getEventTriggerRegistry().executeEventListeners(EventType.GROW, event, new CompoundTag());

			//Execute perks configured by the player
			hookOutput = TagUtils.mergeTags(hookOutput, core.getPerkRegistry().executePerk(EventType.GROW, player, new CompoundTag()));

			//Apply experience gains
			Map<String, Long> xpAward = core.getExperienceAwards(EventType.GROW, event.getPos(), level, player, hookOutput);
			List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange(player);
			core.awardXP(partyMembersInRange, xpAward);
		}
	}

	/**Checks if the block at the provided position is a cascading growth crop.
	 * If true, looks to see if the source of the growth is above or below the
	 * current position and returns that location.  This is used in {@link handle}
	 * to get the owner data from the source block so the new growth can properly
	 * supply XP to the player
	 * 
	 * @param level	ServerLevel object
	 * @param state State of the new growth
	 * @param posIn Location of the new growth
	 * @return source block position
	 */
	private static BlockPos getParentPos(Level level, BlockState state, BlockPos posIn) {
		if (state.is(Reference.CASCADING_BREAKABLES)) 
			return level.getBlockState(posIn.above()).isAir() && level.getBlockState(posIn.below()).is(Reference.CASCADING_BREAKABLES)
					? posIn.below() 
					: level.getBlockState(posIn.below()).isAir() && level.getBlockState(posIn.above()).is(Reference.CASCADING_BREAKABLES)
						? posIn.above()
						: posIn;
		else
			return posIn;
	}
}

package harmonised.pmmo.events.impl;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

import com.mojang.authlib.GameProfile;

import harmonised.pmmo.api.APIUtils;
import harmonised.pmmo.api.enums.EventType;
import harmonised.pmmo.api.events.FurnaceBurnEvent;
import harmonised.pmmo.core.Core;
import harmonised.pmmo.features.party.PartyUtils;
import harmonised.pmmo.storage.ChunkDataHandler;
import harmonised.pmmo.storage.ChunkDataProvider;
import harmonised.pmmo.storage.IChunkData;
import harmonised.pmmo.util.TagUtils;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;


public class FurnaceHandler {

	@SuppressWarnings("resource")
	public static void handle(FurnaceBurnEvent event) {
		//Checkers to exit early for non-applicable conditions
		if (event.getLevel().isClientSide) return;
		IChunkData cap = event.getLevel().getChunkAt(event.getPos()).getCapability(ChunkDataProvider.CHUNK_CAP).orElseGet(ChunkDataHandler::new);
		UUID pid = cap.checkPos(event.getPos());
		if (pid == null) return;
		ServerPlayer player = event.getLevel().getServer().getPlayerList().getPlayer(pid);
		if (player == null) {
			Optional<GameProfile> playerProfile = event.getLevel().getServer().getProfileCache().get(pid);
			if (playerProfile.isEmpty()) 
				return;
			player = new ServerPlayer(event.getLevel().getServer(), (ServerLevel) event.getLevel(), playerProfile.get());
		}

		//core logic 
		Core core = Core.get(event.getLevel());
		CompoundTag eventHook = core.getEventTriggerRegistry().executeEventListeners(EventType.SMELT, event, new CompoundTag());
		eventHook.putString(APIUtils.STACK, event.getInput().serializeNBT().getAsString());
		eventHook = TagUtils.mergeTags(eventHook, core.getPerkRegistry().executePerk(EventType.SMELT, player, eventHook));
		Map<String, Long> xpAwards = core.getExperienceAwards(EventType.SMELT, event.getInput(), player, eventHook);
		core.getExperienceAwards(EventType.SMELTED, event.getOutput(), player, eventHook).forEach((skill, award) -> xpAwards.merge(skill, award, Long::sum));
		List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange(player);
		core.awardXP(partyMembersInRange, xpAwards);

	}
}

package harmonised.pmmo.events.impl;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

import harmonised.pmmo.storage.ChunkDataProvider;
import harmonised.pmmo.util.Reference;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.piston.PistonStructureResolver;
import net.minecraft.world.level.chunk.LevelChunk;
import net.minecraftforge.event.level.PistonEvent;

public class PistonHandler {

	 public static void handle(PistonEvent.Pre event) {
		 if (event.getLevel().isClientSide()) return;


		 Level level = (Level) event.getLevel();
		 PistonStructureResolver structure = event.getStructureHelper();
		 structure.resolve();

		 for (BlockPos destroyed : structure.getToDestroy()) {
			 LevelChunk ck = level.getChunkAt(destroyed);
			 ck.getCapability(ChunkDataProvider.CHUNK_CAP).ifPresent(cap -> {
				 cap.delPos(destroyed);
			 });
			 ck.setUnsaved(true);
		 }		 
		 Map<BlockPos, UUID> updateToMap = new HashMap<>();
		 for (BlockPos moved : structure.getToPush()) {
			 LevelChunk oldCK = level.getChunkAt(moved);			 
			 UUID currentID = oldCK.getCapability(ChunkDataProvider.CHUNK_CAP).map(cap -> cap.checkPos(moved)).orElse(Reference.NIL);
			 if (currentID.equals(Reference.NIL)) continue;
			 oldCK.getCapability(ChunkDataProvider.CHUNK_CAP).ifPresent(cap -> {
				 cap.delPos(moved);
			 });
			 updateToMap.put( moved.relative(event.getStructureHelper().getPushDirection()), currentID);
			 oldCK.setUnsaved(true);
		 }
		 for (Map.Entry<BlockPos, UUID> map : updateToMap.entrySet()) {
			 LevelChunk toCK = level.getChunkAt(map.getKey());
			 toCK.getCapability(ChunkDataProvider.CHUNK_CAP).ifPresent(cap -> {
				 cap.addPos(map.getKey(), map.getValue());
			 });
			 toCK.setUnsaved(true);
		 }
	 }
}

